//java.lang.Thread.sleep(500); //Simulate latency

tw.local.multiDataSeries = new tw.object.listOf.DataSeries();

for(var j = 0; j < 5; j++)
{
    var dataSeries = new tw.object.DataSeries();

    dataSeries.seriesName = "Sample " + j;
    dataSeries.dataPoints = new tw.object.listOf.DataPoint();

    var i = 0;

    dataSeries.dataPoints[i] = new tw.object.DataPoint();
    dataSeries.dataPoints[i].value = Math.floor(100 * Math.random()) + j;
    dataSeries.dataPoints[i].label = "Category " + i;
    i++;
    dataSeries.dataPoints[i] = new tw.object.DataPoint();
    dataSeries.dataPoints[i].value = Math.floor(100 * Math.random()) + j;
    dataSeries.dataPoints[i].label = "Category " + i;
    i++;
    dataSeries.dataPoints[i] = new tw.object.DataPoint();
    dataSeries.dataPoints[i].value = Math.floor(100 * Math.random()) + j;
    dataSeries.dataPoints[i].label = "Category " + i;
    i++;
    dataSeries.dataPoints[i] = new tw.object.DataPoint();
    dataSeries.dataPoints[i].value = Math.floor(100 * Math.random()) + j;
    dataSeries.dataPoints[i].label = "Category " + i;
    i++;
    dataSeries.dataPoints[i] = new tw.object.DataPoint();
    dataSeries.dataPoints[i].value = Math.floor(100 * Math.random()) + j;
    dataSeries.dataPoints[i].label = "Category " + i;
    i++;

    tw.local.multiDataSeries[tw.local.multiDataSeries.listLength] = dataSeries;
}

